'use strict';

const fs = require('fs');
const path = require('path');
const assert = require('assert');
const ROOT = path.resolve(__dirname, '..', '..');
const core = require(path.join(ROOT, 'system-master', 'book-system', 'version-and-rollback-core.js'));
const fixtures = JSON.parse(fs.readFileSync(path.join(ROOT, 'qualification', 'book-system', 'version-and-rollback-001', 'VERSION-AND-ROLLBACK-FIXTURES-001.json'), 'utf8'));
const contract = JSON.parse(fs.readFileSync(path.join(ROOT, 'qualification', 'book-system', 'version-and-rollback-001', 'BOOK-SYSTEM-VERSION-AND-ROLLBACK-001.json'), 'utf8'));
assert.strictEqual(contract.boundary_id, 'BOOK-SYSTEM-VERSION-AND-ROLLBACK-001');
assert.strictEqual(contract.version_ledger.schema_version, 1);

let passed = 0;
const results = [];
function run(id, fn) { try { fn(); results.push({case_id:id,result:'PASS'}); passed++; } catch(e){ results.push({case_id:id,result:'FAIL',error:e.stack||String(e)}); throw e; } }
function expectCode(fn, code){let seen=null;try{fn();}catch(e){seen=e.code||e.name;}assert.strictEqual(seen,code,`expected ${code}, saw ${seen}`);}

function baseState(status='DRAFTING'){
  return core.sealState({
    schema_version:1,state_version:1,
    book_project:{book_project_id:'BOOKPROJECT:001',book_id:'BOOK:001',status,governing_brief_ref:'BRIEF:001',canonical_manifest_ref:'CANON:001'},
    governing_briefs:{'BRIEF:001':{brief_id:'BRIEF:001',version:1,author_intent:'Preserve intent.',form:'BOOK',genre:'PROJECT_DEFINED',audience:'PROJECT_DEFINED',voice_goals:['PROJECT_SPECIFIC'],hard_constraints:['NO_SILENT_CANON_MUTATION']}},
    canon_manifests:{'CANON:001':{canon_manifest_id:'CANON:001',version:1,facts:[],entities:[],world_rules:[],protected_language_refs:[],intent_constraints:[],approval_state:'APPROVED'}},
    story_bibles:{'STORYBIBLE:001':{story_bible_id:'STORYBIBLE:001',version:1,entity_refs:[],relationship_refs:[],timeline_refs:[],arc_refs:[],motif_theme_refs:[],open_questions:[],provenance:[]}},
    book_plans:{'PLAN:001':{plan_id:'PLAN:001',version:1,part_refs:[],chapter_refs:[],scene_refs:[],dependency_edges:[],purpose_and_payoff_refs:[]}},
    manuscripts:{'MANUSCRIPT:001:V1':{manuscript_id:'MANUSCRIPT:001',version_id:'MANUSCRIPT:001:V1',artifact_digest:'a'.repeat(64),authority_state:'CANONICAL',parent_version_ref:null,change_set_ref:'CHANGESET:000',created_by:'PARENT_SYSTEM',created_at:'2026-09-09T16:00:00Z'}},
    research_evidence_links:{},author_decisions:{},integration_proposals:{},export_releases:{},
    active:{governing_brief_ref:'BRIEF:001',canon_manifest_ref:'CANON:001',story_bible_ref:'STORYBIBLE:001',book_plan_ref:'PLAN:001',canonical_manuscript_ref:'MANUSCRIPT:001:V1'}
  });
}
function proposedV2(state){const p=JSON.parse(JSON.stringify(state));delete p.state_digest;p.manuscripts['MANUSCRIPT:001:V2']={manuscript_id:'MANUSCRIPT:001',version_id:'MANUSCRIPT:001:V2',artifact_digest:'b'.repeat(64),authority_state:'CANONICAL',parent_version_ref:'MANUSCRIPT:001:V1',change_set_ref:'CHANGESET:001',created_by:'PARENT_SYSTEM',created_at:'2026-09-09T17:00:00Z'};p.active.canonical_manuscript_ref='MANUSCRIPT:001:V2';return p;}
function sealCandidate(current, proposed){const p=JSON.parse(JSON.stringify(proposed));p.state_version=current.state_version+1;delete p.state_digest;return core.sealState(p);}
function baseReq(state,ledger,id,key){return{request_id:id,idempotency_key:key,actor_class:'PARENT_SYSTEM',expected_state_version:state.state_version,expected_state_digest:state.state_digest,expected_ledger_version:ledger.ledger_version,expected_ledger_digest:ledger.ledger_digest};}
function successorReq(state,ledger,id,key,proposed,lifecycle=null){const candidate=sealCandidate(state,proposed);return{...baseReq(state,ledger,id,key),proposed_parent_state:proposed,active_version_bindings:core.deriveActiveVersionBindings(state,ledger,candidate),evidence_refs:[],author_decision_refs:[],lifecycle_transition_receipt:lifecycle};}
function lifecycleReceipt(current, proposed, id='TRANSITION-RECEIPT:001'){const next=sealCandidate(current,proposed);return{transition_receipt_id:id,scope:'PROJECT',pre_parent_state_version:current.state_version,pre_parent_state_digest:current.state_digest,from_status:current.book_project.status,to_status:next.book_project.status,post_parent_state_version:next.state_version,post_parent_state_digest:next.state_digest};}
function restoreReq(state,ledger,id,key,target,mode='RESTORE_CONTENT'){
  const targetState=target.canonical_state;
  const changed=Object.keys(targetState.active).filter(f=>state.active[f]!==targetState.active[f]);
  return{...baseReq(state,ledger,id,key),target_state_version:target.state_version,target_state_digest:target.state_digest,mode,revalidation:{rights_privacy_current:true,critical_evidence_resolved:true,dependency_revalidation_refs:['DEPENDENCY:CURRENT'],binding_checks:core.bindingChecksForState(state,ledger,targetState,changed),author_decision_required:false,author_decision_refs:[],lifecycle_transition_receipt:null}};
}

const s0=baseState();const l0=core.initializeLedger(s0);
run('INITIALIZE-LEDGER-001',()=>{core.validateLedger(l0,s0);assert.strictEqual(l0.state_snapshots.length,1);assert.strictEqual(l0.object_version_nodes.length,5);assert.ok(l0.current_snapshot_id);});
const p1=proposedV2(s0);const q1=successorReq(s0,l0,'REQ:001','IDEMP:001',p1);const c1=core.commitSuccessor(s0,l0,q1);
run('COMMIT-SUCCESSOR-001',()=>{assert.strictEqual(c1.state.state_version,2);assert.strictEqual(c1.state.active.canonical_manuscript_ref,'MANUSCRIPT:001:V2');core.validateLedger(c1.ledger,c1.state);});
run('OBJECT-PREDECESSOR-LINK-001',()=>{const n=c1.ledger.object_version_nodes.find(x=>x.storage_ref==='MANUSCRIPT:001:V2');const pred=c1.ledger.object_version_nodes.find(x=>x.storage_ref==='MANUSCRIPT:001:V1');assert.strictEqual(n.predecessor_node_id,pred.node_id);});
run('REJECT-OBJECT-IDENTITY-DIGEST-CONFLICT-001',()=>{const p=JSON.parse(JSON.stringify(s0));delete p.state_digest;p.manuscripts['MANUSCRIPT:001:V1-ALT']={...p.manuscripts['MANUSCRIPT:001:V1'],artifact_digest:'c'.repeat(64)};p.active.canonical_manuscript_ref='MANUSCRIPT:001:V1-ALT';expectCode(()=>core.commitSuccessor(s0,l0,successorReq(s0,l0,'REQ:OID','IDEMP:OID',p)),'OBJECT_VERSION_IDENTITY_DIGEST_CONFLICT');});
run('REJECT-GOVERNED-HISTORY-MUTATION-001',()=>{const p=proposedV2(s0);p.governing_briefs['BRIEF:001'].author_intent='mutated';expectCode(()=>core.commitSuccessor(s0,l0,successorReq(s0,l0,'REQ:GHM','IDEMP:GHM',p)),'GOVERNED_HISTORY_MUTATION');});
run('REJECT-STATE-VERSION-STALE-001',()=>{const q=successorReq(c1.state,c1.ledger,'REQ:SVER','IDEMP:SVER',c1.state);q.expected_state_version=1;expectCode(()=>core.commitSuccessor(c1.state,c1.ledger,q),'STATE_VERSION_MISMATCH');});
run('REJECT-STATE-DIGEST-STALE-001',()=>{const q=successorReq(c1.state,c1.ledger,'REQ:SDIG','IDEMP:SDIG',c1.state);q.expected_state_digest='0'.repeat(64);expectCode(()=>core.commitSuccessor(c1.state,c1.ledger,q),'STATE_DIGEST_MISMATCH');});
run('REJECT-LEDGER-VERSION-STALE-001',()=>{const q=successorReq(c1.state,c1.ledger,'REQ:LVER','IDEMP:LVER',c1.state);q.expected_ledger_version=1;expectCode(()=>core.commitSuccessor(c1.state,c1.ledger,q),'LEDGER_VERSION_MISMATCH');});
run('REJECT-LEDGER-DIGEST-STALE-001',()=>{const q=successorReq(c1.state,c1.ledger,'REQ:LDIG','IDEMP:LDIG',c1.state);q.expected_ledger_digest='0'.repeat(64);expectCode(()=>core.commitSuccessor(c1.state,c1.ledger,q),'LEDGER_DIGEST_MISMATCH');});
run('IDEMPOTENT-REPLAY-001',()=>{const r=core.commitSuccessor(c1.state,c1.ledger,q1);assert.strictEqual(r.replayed,true);assert.strictEqual(r.receipt.receipt_id,c1.receipt.receipt_id);});
run('REJECT-IDEMPOTENCY-CONFLICT-001',()=>{const q=JSON.parse(JSON.stringify(q1));q.proposed_parent_state.book_project.status='STRUCTURAL_REVIEW';expectCode(()=>core.commitSuccessor(c1.state,c1.ledger,q),'IDEMPOTENCY_KEY_CONFLICT');});
run('REJECT-REQUEST-ID-CONFLICT-001',()=>{const q=successorReq(c1.state,c1.ledger,q1.request_id,'IDEMP:OTHER',c1.state);expectCode(()=>core.commitSuccessor(c1.state,c1.ledger,q),'REQUEST_ID_CONFLICT');});
run('CONCURRENT-WRITE-STALE-SECOND-001',()=>{const q=successorReq(s0,l0,'REQ:CON2','IDEMP:CON2',proposedV2(s0));expectCode(()=>core.commitSuccessor(c1.state,c1.ledger,q),'STATE_VERSION_MISMATCH');});

let se=JSON.parse(JSON.stringify(s0));delete se.state_digest;se.research_evidence_links['EVIDENCE:001']={link_id:'EVIDENCE:001',claim_or_evidence_ref:'SRC:1',target_book_object_ref:'BOOK:001',freshness_state:'CURRENT',conflict_state:'NONE',provenance:['SRC:1'],rights_class:'AUTHORIZED'};se=core.sealState(se);const le=core.initializeLedger(se);
run('REJECT-APPEND-ONLY-REMOVAL-001',()=>{const p=JSON.parse(JSON.stringify(se));delete p.state_digest;delete p.research_evidence_links['EVIDENCE:001'];expectCode(()=>core.commitSuccessor(se,le,successorReq(se,le,'REQ:AOR','IDEMP:AOR',p)),'APPEND_ONLY_HISTORY_REMOVAL');});
run('REJECT-APPEND-ONLY-MUTATION-001',()=>{const p=JSON.parse(JSON.stringify(se));delete p.state_digest;p.research_evidence_links['EVIDENCE:001'].freshness_state='STALE';expectCode(()=>core.commitSuccessor(se,le,successorReq(se,le,'REQ:AOM','IDEMP:AOM',p)),'APPEND_ONLY_HISTORY_MUTATION');});
run('REJECT-CANONICAL-MANUSCRIPT-DIGEST-001',()=>{const p=proposedV2(s0);p.manuscripts['MANUSCRIPT:001:V2'].artifact_digest='bad';let q;try{q=successorReq(s0,l0,'REQ:BADM','IDEMP:BADM',p);}catch(e){assert.strictEqual(e.code,'CANONICAL_MANUSCRIPT_INVALID');return;}expectCode(()=>core.commitSuccessor(s0,l0,q),'CANONICAL_MANUSCRIPT_INVALID');});
run('REJECT-ACTIVE-BINDING-MISMATCH-001',()=>{const q=successorReq(s0,l0,'REQ:ABM','IDEMP:ABM',proposedV2(s0));q.active_version_bindings.canonical_manuscript_ref.object_digest='0'.repeat(64);expectCode(()=>core.commitSuccessor(s0,l0,q),'ACTIVE_VERSION_BINDING_MISMATCH');});
run('REJECT-LIFECYCLE-WITHOUT-RECEIPT-001',()=>{const p=JSON.parse(JSON.stringify(s0));delete p.state_digest;p.book_project.status='STRUCTURAL_REVIEW';const q=successorReq(s0,l0,'REQ:LC0','IDEMP:LC0',p,null);expectCode(()=>core.commitSuccessor(s0,l0,q),'LIFECYCLE_TRANSITION_RECEIPT_REQUIRED');});
run('VALID-LIFECYCLE-RECEIPT-001',()=>{const p=JSON.parse(JSON.stringify(s0));delete p.state_digest;p.book_project.status='STRUCTURAL_REVIEW';const lr=lifecycleReceipt(s0,p);const q=successorReq(s0,l0,'REQ:LC1','IDEMP:LC1',p,lr);const r=core.commitSuccessor(s0,l0,q);assert.strictEqual(r.state.book_project.status,'STRUCTURAL_REVIEW');});

const target=l0.state_snapshots[0];const rreq=restoreReq(c1.state,c1.ledger,'REQ:R1','IDEMP:R1',target);const restored=core.restoreAsSuccessor(c1.state,c1.ledger,rreq);
run('RESTORE-CONTENT-AS-SUCCESSOR-001',()=>{assert.strictEqual(restored.state.state_version,3);assert.strictEqual(restored.state.active.canonical_manuscript_ref,'MANUSCRIPT:001:V1');assert.strictEqual(restored.state.book_project.status,'DRAFTING');assert.strictEqual(restored.receipt.restored_from_snapshot_id,target.snapshot_id);});
run('REJECT-RESTORE-TARGET-DIGEST-001',()=>{const q=restoreReq(c1.state,c1.ledger,'REQ:RTD','IDEMP:RTD',target);q.target_state_digest='0'.repeat(64);expectCode(()=>core.restoreAsSuccessor(c1.state,c1.ledger,q),'RESTORE_TARGET_NOT_FOUND_OR_DIGEST_MISMATCH');});
run('REJECT-CONTENT-RESTORE-FROZEN-001',()=>{const sf=baseState('EXPORT_FROZEN');const lf=core.initializeLedger(sf);const q=restoreReq(sf,lf,'REQ:FR','IDEMP:FR',lf.state_snapshots[0]);expectCode(()=>core.restoreAsSuccessor(sf,lf,q),'CONTENT_RESTORE_FORBIDDEN_AT_CURRENT_STATUS');});
run('REJECT-RIGHTS-PRIVACY-REVALIDATION-001',()=>{const q=restoreReq(c1.state,c1.ledger,'REQ:RRP','IDEMP:RRP',target);q.revalidation.rights_privacy_current=false;expectCode(()=>core.restoreAsSuccessor(c1.state,c1.ledger,q),'RIGHTS_PRIVACY_REVALIDATION_REQUIRED');});
run('REJECT-CRITICAL-EVIDENCE-001',()=>{const q=restoreReq(c1.state,c1.ledger,'REQ:RCE','IDEMP:RCE',target);q.revalidation.critical_evidence_resolved=false;expectCode(()=>core.restoreAsSuccessor(c1.state,c1.ledger,q),'CRITICAL_EVIDENCE_UNRESOLVED');});
run('REJECT-BINDING-CURRENTNESS-001',()=>{const q=restoreReq(c1.state,c1.ledger,'REQ:RBC','IDEMP:RBC',target);q.revalidation.binding_checks=[];expectCode(()=>core.restoreAsSuccessor(c1.state,c1.ledger,q),'CURRENT_BINDING_REVALIDATION_REQUIRED');});
run('REJECT-CURRENT-EVIDENCE-REF-001',()=>{const q=restoreReq(c1.state,c1.ledger,'REQ:RER','IDEMP:RER',target);q.revalidation.dependency_revalidation_refs=[];for(const x of q.revalidation.binding_checks)x.evidence_refs=[];expectCode(()=>core.restoreAsSuccessor(c1.state,c1.ledger,q),'CURRENT_EVIDENCE_OR_DEPENDENCY_REF_REQUIRED');});
run('REJECT-AUTHOR-DECISION-MISSING-001',()=>{const q=restoreReq(c1.state,c1.ledger,'REQ:AD0','IDEMP:AD0',target);q.revalidation.author_decision_required=true;q.revalidation.author_decision_refs=[];expectCode(()=>core.restoreAsSuccessor(c1.state,c1.ledger,q),'AUTHOR_DECISION_REQUIRED');});

let sa=JSON.parse(JSON.stringify(c1.state));delete sa.state_digest;sa.author_decisions['DECISION:BAD']={decision_id:'DECISION:BAD',subject_ref:'MANUSCRIPT:001:V1',decision_type:'RESTORE',options:['APPROVE','REJECT'],status:'PENDING',author_choice:null,effective_version:2};sa=core.sealState(sa);let la=core.initializeLedger(sa);la.state_snapshots.unshift(JSON.parse(JSON.stringify(target)));la.ledger_digest=core.computeLedgerDigest(la);
