let sg=JSON.parse(JSON.stringify(c1.state));delete sg.state_digest;sg.author_decisions['DECISION:GOOD']={decision_id:'DECISION:GOOD',subject_ref:'MANUSCRIPT:001:V1',decision_type:'RESTORE',options:['APPROVE','REJECT'],status:'APPROVED',author_choice:'APPROVE',effective_version:2};sg=core.sealState(sg);let lg=core.initializeLedger(sg);lg.state_snapshots.unshift(JSON.parse(JSON.stringify(target)));lg.ledger_digest=core.computeLedgerDigest(lg);
run('VALID-AUTHOR-DECISION-REVALIDATION-001',()=>{const q=restoreReq(sg,lg,'REQ:ADG','IDEMP:ADG',target);q.revalidation.author_decision_required=true;q.revalidation.author_decision_refs=['DECISION:GOOD'];const r=core.restoreAsSuccessor(sg,lg,q);assert.strictEqual(r.state.author_decisions['DECISION:GOOD'].status,'APPROVED');});
run('RESTORE-PRESERVES-NEWER-NODES-001',()=>{assert.ok(restored.state.manuscripts['MANUSCRIPT:001:V2']);assert.ok(restored.ledger.object_version_nodes.some(x=>x.storage_ref==='MANUSCRIPT:001:V2'));});
run('DIVERGENT-SUCCESSOR-LINEAGE-001',()=>{const p=JSON.parse(JSON.stringify(restored.state));delete p.state_digest;p.manuscripts['MANUSCRIPT:001:V3']={manuscript_id:'MANUSCRIPT:001',version_id:'MANUSCRIPT:001:V3',artifact_digest:'c'.repeat(64),authority_state:'CANONICAL',parent_version_ref:'MANUSCRIPT:001:V1',change_set_ref:'CHANGESET:BRANCH',created_by:'PARENT_SYSTEM',created_at:'2026-09-09T18:00:00Z'};p.active.canonical_manuscript_ref='MANUSCRIPT:001:V3';const q=successorReq(restored.state,restored.ledger,'REQ:DIV','IDEMP:DIV',p);const r=core.commitSuccessor(restored.state,restored.ledger,q);const heads=r.ledger.object_family_heads['MANUSCRIPT_MANIFEST|MANUSCRIPT:001'];assert.strictEqual(heads.length,2);});
