run('REJECT-FULL-STATE-WITHOUT-PUBLICATION-AUTHORITY-001',()=>{const sf=baseState('EXPORT_FROZEN');const lf=core.initializeLedger(sf);const q=restoreReq(sf,lf,'REQ:FULL','IDEMP:FULL',lf.state_snapshots[0],'RESTORE_FULL_STATE');expectCode(()=>core.restoreAsSuccessor(sf,lf,q),'CURRENT_PUBLICATION_AUTHORITY_EVIDENCE_REQUIRED');});
run('ATOMIC-FAILPOINT-001',()=>{const beforeS=core.stable(c1.state),beforeL=core.stable(c1.ledger);const q=restoreReq(c1.state,c1.ledger,'REQ:FP','IDEMP:FP',target);q.failpoint='BEFORE_COMMIT';expectCode(()=>core.restoreAsSuccessor(c1.state,c1.ledger,q),'INJECTED_BEFORE_COMMIT');assert.strictEqual(core.stable(c1.state),beforeS);assert.strictEqual(core.stable(c1.ledger),beforeL);});
