assert.strictEqual(results.length,fixtures.cases.length);
const summary={qualification_id:'BOOK-SYSTEM-VERSION-AND-ROLLBACK-001',standing:'HOSTED_PREQUALIFICATION_PASS',subject_sha:process.env.GITHUB_SHA||null,cases_total:fixtures.cases.length,cases_passed:passed,state_digest:c1.state.state_digest,ledger_digest:c1.ledger.ledger_digest,author_authority_synthesized:false,publication_authority_synthesized:false,results};
